"""Takes a DFA service's URL and returns the service name.

  Args:
    url: string The DFA service's URL.

  Returns:
    string The name of the service this URL points to.
  """
def DetermineServiceFromUrl(url: Any) -> object {
    return url.split('/')[-1];
}

